Kalau tugas sudah banyak, pengguna ingin melihat **yang belum selesai saja** atau **yang sudah selesai saja**. Fitur ini butuh satu state baru: filter yang sedang dipilih.

```jsx
const [filter, setFilter] = useState('semua');
```

Daftar yang ditampilkan **tidak disimpan** di state. Ia dihitung dari `tugas` dan `filter` setiap render:

```jsx
const FILTER = {
  semua: () => true,
  aktif: (t) => !t.selesai,
  selesai: (t) => t.selesai,
};

const tampil = tugas.filter(FILTER[filter]);
```

Ibarat **kacamata berwarna**: buku yang dibaca tetap sama, hanya cara melihatnya yang diganti. Data tugas tidak berubah saat filter dipilih.

Objek `FILTER` berisi satu fungsi untuk setiap pilihan. `FILTER['aktif']` adalah fungsi `(t) => !t.selesai`, yang langsung bisa diberikan ke `filter`.

### Tombol filter

```jsx
function PilihFilter({ nilai, onPilih }) {
  return (
    <div className="filter" role="group" aria-label="Filter tugas">
      {Object.keys(FILTER).map((nama) => (
        <button key={nama} type="button" aria-pressed={nilai === nama} onClick={() => onPilih(nama)}>
          {nama[0].toUpperCase() + nama.slice(1)}
        </button>
      ))}
    </div>
  );
}
```

| Bagian | Fungsi |
|---|---|
| `Object.keys(FILTER)` | `['semua', 'aktif', 'selesai']`, tombol dibuat dari data |
| `aria-pressed` | menandai tombol yang aktif (juga dipakai CSS untuk mewarnainya) |
| `nama[0].toUpperCase() + nama.slice(1)` | "aktif" ditampilkan "Aktif" |

### Hapus yang selesai

Satu fitur kecil lagi, tombol yang menghapus semua tugas selesai sekaligus:

```jsx
function hapusSelesai() {
  setTugas(tugas.filter((t) => !t.selesai));
}

{tugas.some((t) => t.selesai) && <button onClick={hapusSelesai}>Hapus yang selesai</button>}
```

`some` mengembalikan `true` kalau ada minimal satu tugas yang selesai; tombolnya hanya tampil saat berguna.

cards.code:
import { useState } from 'react';

const awal = [
  { id: 1, teks: 'Belajar JSX', selesai: true },
  { id: 2, teks: 'Belajar state', selesai: false },
  { id: 3, teks: 'Membuat todolist', selesai: false },
];

const FILTER = {
  semua: () => true,
  aktif: (t) => !t.selesai,
  selesai: (t) => t.selesai,
};

function PilihFilter({ nilai, onPilih }) {
  return (
    <div className="filter" role="group" aria-label="Filter tugas">
      {Object.keys(FILTER).map((nama) => (
        <button key={nama} type="button" aria-pressed={nilai === nama} onClick={() => onPilih(nama)}>
          {nama[0].toUpperCase() + nama.slice(1)}
        </button>
      ))}
    </div>
  );
}

function FormTambah({ onTambah }) {
  const [teks, setTeks] = useState('');

  function handleSubmit(e) {
    e.preventDefault();
    const bersih = teks.trim();
    if (bersih === '') return;
    onTambah(bersih);
    setTeks('');
  }

  return (
    <form className="baris" onSubmit={handleSubmit}>
      <input type="text" value={teks} onChange={(e) => setTeks(e.target.value)} placeholder="Tugas baru" />
      <button type="submit">Tambah</button>
    </form>
  );
}

function ItemTugas({ tugas, onCentang, onHapus }) {
  return (
    <li className={tugas.selesai ? 'selesai' : ''}>
      <input type="checkbox" checked={tugas.selesai} onChange={() => onCentang(tugas.id)}
        aria-label={`Tandai ${tugas.teks} selesai`} />
      <span>{tugas.teks}</span>
      <button onClick={() => onHapus(tugas.id)} aria-label={`Hapus ${tugas.teks}`}>✕</button>
    </li>
  );
}

export default function App() {
  const [tugas, setTugas] = useState(awal);
  const [filter, setFilter] = useState('semua');

  function tambah(teks) {
    setTugas([...tugas, { id: crypto.randomUUID(), teks, selesai: false }]);
  }
  function centang(id) {
    setTugas(tugas.map((t) => (t.id === id ? { ...t, selesai: !t.selesai } : t)));
  }
  function hapus(id) {
    setTugas(tugas.filter((t) => t.id !== id));
  }
  function hapusSelesai() {
    setTugas(tugas.filter((t) => !t.selesai));
  }

  const tampil = tugas.filter(FILTER[filter]);
  const sisa = tugas.filter((t) => !t.selesai).length;
  const adaSelesai = tugas.some((t) => t.selesai);

  return (
    <div className="todo">
      <h1>Todolist</h1>
      <FormTambah onTambah={tambah} />
      <ul className="daftar">
        {tampil.map((t) => <ItemTugas key={t.id} tugas={t} onCentang={centang} onHapus={hapus} />)}
      </ul>
      {tampil.length === 0 && <p className="kecil">Tidak ada tugas di sini.</p>}
      <PilihFilter nilai={filter} onPilih={setFilter} />
      <p className="kecil">
        {sisa} tugas belum selesai{' '}
        {adaSelesai && <button type="button" onClick={hapusSelesai}>Hapus yang selesai</button>}
      </p>
    </div>
  );
}

